use verus::prelude::*;

// A small helper spec function that characterizes ASCII letters.
#[verifier::spec]
fn is_ascii_letter(c: char) -> bool {
    ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z')
}

// A pure‐specification of what we mean by
// "the last character is an ASCII letter and, if there is a character
// just before it, that character is a space."
#[verifier::spec]
fn spec_check_if_last_char_is_a_letter(txt: &str) -> bool {
    // Count how many `char`s there are in the string:
    let len: usize = txt.chars().count();
    if len == 0 {
        // empty ⇒ false
        false
    } else {
        // Safe to unwrap because len > 0
        let last = txt.chars().nth(len - 1).unwrap();
        if !is_ascii_letter(last) {
            // last character not an ASCII letter ⇒ false
            false
        } else if len == 1 {
            // exactly one character and it is ASCII ⇒ true
            true
        } else {
            // at least two characters: check the one just before the last
            txt.chars().nth(len - 2).unwrap() == ' '
        }
    }
}

#[requires(true)]
#[ensures(result == spec_check_if_last_char_is_a_letter(txt))]
fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    let mut rev_chars = txt.chars().rev();

    // 1) The string must be non-empty and have an ASCII letter as its last character.
    let _last = match rev_chars.next() {
        Some(c) if c.is_ascii_alphabetic() => c,
        _ => return false,
    };

    // 2) If there's a preceding character, it must be a space. 
    //    Otherwise (i.e. the string is exactly one character), we succeed.
    match rev_chars.next() {
        Some(prev) => prev == ' ',
        None => true,
    }
}

